document.addEventListener("DOMContentLoaded",(()=>{const e=document.getElementById("signupForm"),t=document.getElementById("signupMessage"),a=document.getElementById("signupSubmit");e.addEventListener("submit",(async s=>{s.preventDefault();const n={firstName:e.firstName.value.trim(),lastName:e.lastName.value.trim(),email:e.email.value.trim(),phone:e.phone.value.trim(),password:e.password.value};if(t.className="form-message",t.textContent="",!(n.firstName&&n.lastName&&n.email&&n.password))return t.className="form-message error",void(t.textContent="Complete the required fields to create your account.");if(n.password.length<8)return t.className="form-message error",void(t.textContent="Your password must be at least 8 characters.");a.disabled=!0,a.textContent="Creating account...";try{await RotimaticApi.signup(n),window.location.href="dashboard.html"}catch(e){t.className="form-message error",t.textContent=e.status>=500?"We could not create your account right now.":e.message}finally{a.disabled=!1,a.textContent="Create account"}}))}));